import pandas as pd
import matplotlib.pyplot as plt

# Load the benchmark CSV generated by benchmark_l2_cuda.py.
df = pd.read_csv("results/cuda_l2/raw/d384_timings.csv")

pivot = df.pivot_table(
    index=["database_size", "query_count"],
    columns="backend",
    values="median_ms",
    aggfunc="median",
).reset_index()

pivot["speedup"] = pivot["cuda_fortran"] / pivot["cuda_cublas"]

fig, ax = plt.subplots(figsize=(10, 6))
for database_size, group in pivot.groupby("database_size"):
    group = group.sort_values("query_count")
    ax.plot(
        group["query_count"],
        group["speedup"],
        marker="o",
        linewidth=2,
        label=f"N = {database_size:,}",
    )

ax.axhline(1.0, color="black", linestyle="--", linewidth=1.2,
           label="Crossover (1.0×)")
ax.set_xscale("log", base=2)
ax.set_xticks([1, 2, 4, 8, 32, 96])
ax.set_xticklabels(["1", "2", "4", "8", "32", "96"])
ax.set_xlabel("Query batch size (Q)")
ax.set_ylabel("Speedup: direct CUDA time / expanded cuBLAS time")
ax.set_title("Squared-L2 crossover at dimension 384 on NVIDIA GeForce MX450")
ax.grid(True, which="both", alpha=0.3)
ax.legend()
fig.tight_layout()
fig.savefig("cuda_l2_speedup_chart.png", dpi=200, bbox_inches="tight")